const text = $input.item.json.body?.text || '';

const regex = /-?\d+(\.\d+)?/g;
const matches = text.match(regex);

if (!matches) return [{ json: { error: 'No hay datos' } }];

const nums = matches.map(Number);

const ingresos = nums.filter(n => n > 0);
const reembolsos = nums.filter(n => n < 0);
const leads_totales = nums.length;

const total_ingresos = ingresos.reduce((a,b) => a+b, 0);
const total_reembolsos = Math.abs(reembolsos.reduce((a,b) => a+b, 0));
const net_revenue = total_ingresos - total_reembolsos;

const high_ticket = ingresos.filter(n => n >= 500);
const mid_ticket = ingresos.filter(n => n >= 100 && n < 500);
const low_ticket = ingresos.filter(n => n > 0 && n < 100);

// LÓGICA CONDICIONAL DIRECTA EN CÓDIGO (Sin Switch Node para evitar errores de Webhook)
let status = 'WARNING';
let mensaje = '⚠️ Net Revenue por debajo del objetivo. Revisar tasa de churn y reembolsos.';

if (net_revenue >= 1000) {
    status = 'SUCCESS';
    mensaje = '¡Meta de ventas superada! 🚀 Excelente trabajo de conversión.';
}

const sorted = [...nums].sort((a,b) => a-b);

return {
  json: {
    cantidad: leads_totales,
    suma: net_revenue,
    promedio: ingresos.length ? Number((total_ingresos / ingresos.length).toFixed(2)) : 0,
    minimo: sorted[0] || 0,
    maximo: sorted[sorted.length - 1] || 0,
    lista_desc: [...sorted].reverse(),
    lista_asc: sorted,
    positivos: ingresos.sort((a,b)=>b-a),
    negativos: reembolsos.sort((a,b)=>a-b),
    crm_data: {
      status: status,
      mensaje: mensaje,
      embudo: {
        leads: leads_totales,
        conversiones: ingresos.length,
        tasa_conversion: leads_totales > 0 ? ((ingresos.length / leads_totales) * 100).toFixed(1) + '%' : '0%',
        churn_rate: ingresos.length > 0 ? ((reembolsos.length / ingresos.length) * 100).toFixed(1) + '%' : '0%'
      },
      finanzas: {
        gross_revenue: total_ingresos,
        refunds: total_reembolsos,
        net_revenue: net_revenue,
        ticket_promedio: ingresos.length ? (total_ingresos / ingresos.length).toFixed(2) : 0
      },
      segmentacion: {
        high_ticket: high_ticket.length,
        mid_ticket: mid_ticket.length,
        low_ticket: low_ticket.length
      }
    }
  }
};
